import os

for filename in os.listdir('/data'):
    with open(os.path.join('/data', filename), 'r') as f:
        content = f.read()
        if 'OmniCorp' in content:
            print(f"Found 'OmniCorp' in {filename}")
        else:
            print(f"Did not find 'OmniCorp' in {filename}")
